SEC("xdp")
int xdp_audit_block_ip(struct xdp_md *ctx)
{
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;

    // Verify packet has minimum required length for L2 and L3 parsing
    if (data + sizeof(struct ethhdr) + sizeof(struct iphdr) > data_end)
        return XDP_PASS;

    struct ethhdr *eth = data;
    if (eth->h_proto != bpf_htons(ETH_P_IP))
        return XDP_PASS;

    struct iphdr *ip = data + sizeof(struct ethhdr);
    // Check if source address matches non-compliant host 192.0.2.188
    if (ip->saddr == bpf_htonl(0xC00002BC))
        return XDP_DROP;

    return XDP_PASS;
}

